import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bir görselin doygunluğunu ayarlamak dakikalar sürer. Program kurmazsınız, fotoğrafınız cihazınızdan ayrılmaz ve sonunda doğal renkli bir görsel indirirsiniz.</p>\n<p>Bu yazı, işlemi beş adımda anlatıyor. İster soluk fotoğraf canlandırın ister sert fotoğraf yumuşatın, adımlar aynıdır.</p>\n<p>Sonunda kaydırıcıyı nasıl kullanacağınızı, ten renklerini nasıl koruyacağınızı ve siyah beyaza nasıl çevireceğinizi öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: renkleri değerlendirin</h2>\n<p>Önce fotoğrafa bakın. Soluk mu, canlı mı, turuncu mu? Değerlendirme, ayarı belirler.</p>\n<p>Orijinal fotoğraftan bir yedek alın. Düzenlenen fotoğraf ayrı bir dosyadır; orijinal güvenlik ağınızdır.</p>\n<p>Amacı belirleyin: portre mi, manzara mı, ürün mü? Amaç, ayarı belirler.</p>\n<h2 id=\"step-by-step\">Doygunluğu beş adımda ayarlamak</h2>\n<p>Önce doygunluk aracını açın ve fotoğrafı yükleyin. Önizlemede görselin tamamını görün.</p>\n<p>Ardından kaydırıcıyı hareket ettirin ve sonucu izleyin. Karşılaştırma moduyla farkı görün.</p>\n<p>Son olarak ten renklerini kontrol edip indirin. Önizlemeyi atlamayın.</p>\n<ol>\n<li>Doygunluk aracını açın ve fotoğrafınızı yükleyin.</li>\n<li>Kaydırıcıyı hareket ettirin; soluk fotoğraf için +10 ile +20 arası.</li>\n<li>Hızlı ön ayarı deneyin ya da karşılaştırma moduyla farkı görün.</li>\n<li>Ten renklerini kontrol edin; turuncu görünüyorsa azaltın.</li>\n<li>Sonucu önizlemede kontrol edip indirin.</li>\n</ol>\n<h2 id=\"using-the-slider\">Doygunluk kaydırıcısını kullanmak</h2>\n<p>Doygunluk kaydırıcısı -100 ile +100 arasında işler. Sıfır değeri, orijinal fotoğraf demektir.</p>\n<p>Doygunluğu azar azar artırın; +10 ile +20 arası, çoğu soluk fotoğraf için yeterlidir.</p>\n<p>Doygunlukta aşırıya kaçmayın; +50'nin üzeri, renkleri yapay gösterir ve fotoğrafı bozar.</p>\n<h2 id=\"using-quick-presets\">Hızlı ön ayarları kullanmak</h2>\n<p>Hazır ön ayarlardan seçin; canlı, doğal ve soluk seçenekleri, yaygın düzeltmeleri tek tıkla uygular.</p>\n<p>Ön ayarı seçtikten sonra kaydırıcıyı oynatın. Ön ayar, başlangıç noktasıdır; ince ayar sizindir.</p>\n<p>Ön ayarınızı kaydedin. Aynı düzeltmeyi sürekli uyguluyorsanız iş akışınız hızlanır.</p>\n<h2 id=\"boosting-a-dull-photo\">Soluk bir fotoğrafı canlandırmak</h2>\n<p>Soluk fotoğrafta doygunluğu +10 ile +20 arasında tutun. Renkler canlanır.</p>\n<p>Yeşili kontrol edin. Aşırı yeşil yapay görünür.</p>\n<p>Gökyüzünü kontrol edin. Mavi, doğal kalmalıdır.</p>\n<h2 id=\"muting-a-harsh-photo\">Sert ve cıvıl cıvıl bir fotoğrafı yumuşatmak</h2>\n<p>Sert fotoğrafta doygunluğu azaltın. -10 ile -20 arası, renkleri sakinleştirir.</p>\n<p>Ten renklerini kontrol edin. Cilt doğal görünmelidir.</p>\n<p>Soluk görünüm, düğün ve portrelerde yaygındır. Yumuşak renkler, zarif durur.</p>\n<h2 id=\"converting-to-grayscale\">Tek tıkla siyah beyaza çevirmek</h2>\n<p>Doygunluğu sıfıra indirin. Renk tamamen gider; yalnızca açık ve koyu kalır.</p>\n<p>Siyah beyazda kontrast önemlidir. Kontrastı +10 ile +20 arasında tutun.</p>\n<p>Siyah beyazı önizlemede kontrol edin. Gölgeler ayrıntıyı kaybetmemelidir.</p>\n<h2 id=\"fixing-skin-tones\">Ten renklerini düzeltmek</h2>\n<p>Ten renkleri doygunluğa hassastır. Fazla doygunluk, cildi turuncu yapar.</p>\n<p>Portrelerde doygunluğu +10 ile +15 arasında bırakın; cilt tonunun doğal kalması gerekir.</p>\n<p>Ayar sonrası yüze bakın; ten rengi doğal görünmüyorsa doygunluğu biraz azaltın.</p>\n<h2 id=\"previewing\">İndirmeden önce önizleme</h2>\n<p>Her zaman önizlemeyi kontrol edin. Renkler doğal görünmelidir.</p>\n<p>Karşılaştırma görünümünde orijinali ve düzenlenen sürümü yan yana inceleyin. Fark doğal mı?</p>\n<p>Şüphede kalırsanız doygunluğu azaltın. Hafif düzeltme, aşırı düzeltmeden her zaman iyidir.</p>\n<h2 id=\"choosing-export-format\">Dışa aktarma formatını seçmek</h2>\n<p>Fotoğrafları JPG olarak dışa aktarın. Hafif dosya, paylaşımı kolaylaştırır.</p>\n<p>Saydamlık gerekiyorsa PNG tercih edin. JPG, saydam alanları kaybeder.</p>\n<p>Dışa aktarma kalitesini yüzde 85-90 ayarlayın. Görünür fark olmadan dosya küçülür.</p>\n<h2 id=\"adjusting-on-mobile\">Telefon ve tablette doygunluk ayarlamak</h2>\n<p>Doygunluk aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve kaydırıcıyı hareket ettirin.</p>\n<p>Telefonda ince ayar zordur. Hassas renk ayarı için bilgisayarı tercih edin.</p>\n<p>İndirilenler, İndirilenler klasöründe birikir. Dosyayı bulamazsanız tarayıcının indirme listesini kontrol edin.</p>\n<h2 id=\"troubleshooting\">Doygunlukla yaygın sorunları çözmek</h2>\n<p>Fotoğraf turuncu görünüyorsa doygunluğu azaltın. Ten renkleri ilk bozulanlardır.</p>\n<p>Fotoğraf sahte görünüyorsa doygunluğu azaltın. +30'un üzeri çoğu fotoğrafta yapaydır.</p>\n<p>Kaydırıcı tepki vermiyorsa sayfayı yenileyin. Tarayıcı sorunu, genellikle yenilemeyle çözülür.</p>\n<h2 id=\"saturation-plus-contrast\">Doygunluk ve kontrast: yaygın ikili</h2>\n<p>Doygunluk renkleri, kontrast derinliği artırır. İkisi birlikte kullanıldığında fotoğraf canlanır.</p>\n<p>Önce doygunluğu, sonra kontrastı ayarlayın. Sıralama, doğru dengeyi bulmanızı sağlar.</p>\n<p>İkisini birlikte abartmayın. Aşırı doygunluk ve kontrast, fotoğrafı yapay gösterir.</p>\n<h2 id=\"saturation-for-social\">Sosyal medya için doygunluk</h2>\n<p>Sosyal medyada fotoğraflar canlı görünmelidir. Doygunluğu +10 ile +20 arasında tutun.</p>\n<p>Ten renklerini kontrol edin. Portrelerde doygunluğu düşük tutun.</p>\n<p>Tüm gönderilerde aynı ayarı kullanın. Tutarlılık, profilinizi tanınır kılar.</p>\n<h2 id=\"saving-settings\">Ayarları bir dahaki sefer için kaydetmek</h2>\n<p>Ayar değerlerini not edin. Aynı düzeltmeyi sürekli yapıyorsanız sayıları kaydedin.</p>\n<p>Kendi ön ayarınızı kaydedin. Tek tıkla aynı düzeltmeyi uygulayın.</p>\n<p>Ayarlarınızı ekiple paylaşın. Tutarlı düzenleme, markayı güçlendirir.</p>\n<h2 id=\"quick-tips\">Daha iyi doygunluk için hızlı ipuçları</h2>\n<p>Küçük adımlarla ayarlayın. +10 ile başlayın, gerekirse artırın.</p>\n<p>Ten renklerini izleyin. Cilt turuncu görünüyorsa doygunluğu azaltın.</p>\n<p>Orijinali koruyun. Düzenlenen fotoğraf ayrı bir dosyadır.</p>\n<h2 id=\"saturation-for-sunset\">Gün batımı fotoğrafı için doygunluk ayarlamak</h2>\n<p>Gün batımında doygunluğu +15 ile +25 arasında tutun. Turuncu ve pembe canlanır.</p>\n<p>Gökyüzünü kontrol edin. Renkler doğal kalmalıdır; elektrik tonları yapaydır.</p>\n<p>Güneşi kontrol edin. Parlak alanlar beyazlamamalıdır.</p>\n<p>Adım adım ilerleyin ve her fotoğrafı indirmeden önce kontrol edin. Kılavuzun tamamı için <a href=\"/tr/blog/gorsel-doygunluk-duzenleyici-rehberi\">Doygunluk düzenleyici kılavuzuna</a> bakın; karşılaştırma için <a href=\"/tr/blog/doygunluk-vs-canlilik\">doygunluk ve canlılık karşılaştırması</a> yardımcı olur. Kontrast için <a href=\"/tr/gorsel-kontrast-ayarla\">görsel kontrast düzenleyici</a>, filtreler için <a href=\"/tr/gorsel-filtreleri\">görsel filtreler</a> hazırdır; araç ise <a href=\"/tr/gorsel-doygunluk-ayarla\">görsel doygunluk düzenleyici</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Telefonda bir fotoğrafın rengini nasıl canlandırırım?","answer":"Doygunluk aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve kaydırıcıyı +10 ile +20 arasına hareket ettirin. Ten renklerini kontrol edin. Hassas ayar için bilgisayarı tercih edin."},{"question":"Manzara fotoğrafı için hangi doygunluk değerini kullanmalıyım?","answer":"+15 ile +25 arası genellikle yeterlidir. Gökyüzü ve çimen canlanır. Yeşili kontrol edin; aşırı yeşil yapay görünür. Gökyüzü doğal kalmalıdır."},{"question":"Renkli bir fotoğrafı siyah beyaza nasıl çeviririm?","answer":"Doygunluğu sıfıra indirin; renk tamamen gider. Siyah beyazda kontrast önemlidir; kontrastı +10 ile +20 arasında tutun. Gölgelerin ayrıntıyı kaybetmediğini kontrol edin."},{"question":"Yemek fotoğrafım doygunluğu artırdıktan sonra neden sahte görünüyor?","answer":"Çünkü doygunluğu fazla artırdınız; renkler yapay göründü. Yemek fotoğraflarında +10 ile +20 arası yeterlidir. Kırmızıyı kontrol edin; domates doğal kırmızı olmalıdır."},{"question":"Doygunluğu mu kontrastı mı önce ayarlamalıyım?","answer":"Önce doygunluğu ayarlayın, sonra kontrastı. Doygunluk renkleri, kontrast derinliği artırır. İkisini birlikte abartmayın; aşırı doygunluk ve kontrast fotoğrafı yapay gösterir."},{"question":"İndirdikten sonra doygunluk değişikliğini geri alabilir miyim?","answer":"Hayır, indirilen dosya geri alınamaz. Bu yüzden orijinal fotoğrafı saklayın. Orijinal dururken istediğiniz zaman yeniden düzenleyebilirsiniz."}];
